import hourliesResults from "./assets/hourlies_results.json";

type HourliesResultsJson = {
  values?: unknown;
};

const buildTopGuessPercentages = (
  countsByQuest: Record<string, Record<string, number>>,
): Record<string, { input: string; percentage: number }[] | undefined> => {
  const result: Record<
    string,
    { input: string; percentage: number }[] | undefined
  > = {};
  for (const [questSlug, countsObj] of Object.entries(countsByQuest)) {
    const entries = Object.entries(countsObj);
    const total = entries.reduce((acc, [, c]) => acc + c, 0);
    if (total === 0) {
      result[questSlug] = [];
      continue;
    }
    const sorted = entries.sort((a, b) => b[1] - a[1]);
    const top = sorted.slice(0, 5).map(([input, cnt]) => ({
      input,
      percentage: Number(((cnt / total) * 100).toFixed(1)),
    }));
    const otherCount = sorted.slice(5).reduce((acc, [, c]) => acc + c, 0);
    if (otherCount > 0) {
      const otherPct = Number(((otherCount / total) * 100).toFixed(1));
      top.push({ input: "Other", percentage: otherPct });
    }
    result[questSlug] = top;
  }
  return result;
};

const hourliesResultsJson = hourliesResults as HourliesResultsJson;
const rawValues: unknown[] = Array.isArray(hourliesResultsJson.values)
  ? hourliesResultsJson.values
  : [];
const countsByQuest = Object.fromEntries(
  rawValues.flatMap((rawEntry) => {
    if (!Array.isArray(rawEntry) || rawEntry.length < 2) {
      return [];
    }
    const entry = rawEntry as unknown[];
    const slugValue = entry[0];
    const countsValue = entry[1];
    if (
      typeof slugValue !== "string" ||
      !countsValue ||
      typeof countsValue !== "object"
    ) {
      return [];
    }
    return [[slugValue, countsValue as Record<string, number>]];
  }),
);

export const STATIC_HOURLIES_TOP_GUESSES =
  buildTopGuessPercentages(countsByQuest);

export const STATIC_HOURLIES_COUNTS_BY_QUEST = countsByQuest;

export const STATIC_HOURLIES_TOTAL_RESPONSES = Object.fromEntries(
  Object.entries(countsByQuest).map(([slug, counts]) => [
    slug,
    Object.values(counts ?? {}).reduce((acc, value) => acc + value, 0),
  ]),
);
